@startuml

enum Color {
  WHITE
  BLACK
}

enum ActionCardType {
  ROLL_DIE_FOR_EXTRA_TURN
  CONNECT_TWO_ADJACENT_TILES
  REMOVE_CONNECTION_PIECE
  MOVE_TO_ARBITRARY_TILE
  LOSE_NEXT_TURN
}

class Game {
  + spareConnectionPieces : int = 32
  + numberOfActionCards : int = 32
}

class Tile {
  + color : Color
}

class ActionTile extends Tile {
  + turnsUntilActive : int
}

class HiddenTile extends Tile {}

class RegularTile extends Tile {}

class ConnectionPiece {}

class Deck {
}

class ActionCard {
  + type : ActionCardType
}

class Player {
  + color : Color
}

class Die {}

Game "1" *-- "1..*" Tile
Game "1" *-- "1" Deck
Game "1" *-- "2..4" Player
Game "1" --> "0..1" Player : currentPlayer
Game "1" --> "1" Die
Deck "1" *-- "32" ActionCard
Tile "1" -- "0..4" ConnectionPiece : connection
ConnectionPiece "1" -- "1" Tile : connects

@enduml

